B.bh6=s([B.cEU,B.cOs,B.cOb],t.G)
B.cuQ=new A.d1("sidescroller","A real-time side-scrolling platformer with its own game loop (joystick + jump/attack); optional high-score persistence.",B.bh6,!1)
B.cU_=new A.p("cols",B.af,"Grid columns (default 36).",B.f,null)
B.cTK=new A.p("rows",B.af,"Grid rows (default 24).",B.f,null)
B.cGF=new A.p("seed",B.af,"World seed \u2014 same seed reproduces the same terrain (share to compare designs).",B.f,null)
